def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = 0
    opp_d = 0
    dc = 0
    cd = 0

    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if a == 'C':
            if b == 'D':
                cd += 1
        else:
            if b == 'C':
                dc += 1

    if opp_c == 0:
        return 'D'

    opp_rate = opp_c / n

    recent10_c = sum(1 for a, b in history[-10:] if b == 'C')
    recent15_c = sum(1 for a, b in history[-15:] if b == 'C')

    streak_d = 0
    for a, b in reversed(history):
        if b == 'D':
            streak_d += 1
        else:
            break

    dd_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'D':
            dd_streak += 1
        else:
            break

    if recent10_c <= 1 and opp_rate < 0.35:
        return 'D'

    if streak_d >= 10 and recent10_c <= 2:
        return 'D'

    if last_opp == 'C':
        if opp_d == 0 and n >= 90:
            return 'D'

        if last_my == 'D':
            if dc >= 2 and recent15_c >= 12 and recent10_c >= 8:
                if rng.random() < 0.2:
                    return 'D'
            return 'C'

        if cd <= 1 and recent15_c >= 13 and n >= 70:
            if rng.random() < 0.05:
                return 'D'

        return 'C'

    if last_my == 'D':
        if recent10_c >= 7 and dd_streak <= 2:
            return 'C'
        if recent10_c >= 5 and dd_streak == 1 and dc >= 1 and opp_rate >= 0.5:
            return 'C'
        return 'D'

    if n >= 2 and history[-2][0] == 'D' and recent10_c >= 4:
        return 'C'

    if streak_d == 1 and recent10_c >= 9 and opp_rate >= 0.85:
        return 'C'

    return 'D'
